CREATE OR REPLACE FUNCTION public.evaluation_notify_rank_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE recipient record; BEGIN IF NEW.status<>'Approved' OR OLD.status='Approved' OR NOT EXISTS(SELECT 1 FROM public."Evaluation_Settings" WHERE id='main' AND config->>'rank_notifications'='true' AND coalesce(config->>'notifications','true')='true') THEN RETURN NEW; END IF; FOR recipient IN WITH totals AS (SELECT u."ID" uid,coalesce(sum(t.amount),0) score,coalesce(sum(t.amount) FILTER(WHERE t.id<>NEW.id),0) previous FROM public."Users" u LEFT JOIN public."Points_Transactions" t ON t.user_id=u."ID" AND t.category=NEW.category AND t.status='Approved' WHERE (CASE WHEN u."Role"='Leader' THEN 'Leader' ELSE 'Member' END)=NEW.category AND coalesce(u."Status",'Active') NOT IN ('Pending','Suspended') GROUP BY u."ID"), ranks AS(SELECT uid,rank() OVER(ORDER BY score DESC) current_rank,rank() OVER(ORDER BY previous DESC) previous_rank FROM totals) SELECT * FROM ranks WHERE current_rank<>previous_rank LOOP INSERT INTO public."User_Notifications"("Notification_ID","User_ID","Title","Body","Created_At","Is_Read","Source","Reference_ID") VALUES(gen_random_uuid()::text,recipient.uid,'تغير ترتيبك','ترتيبك الحالي: '||recipient.current_rank::text,now()::text,'False','evaluation_rank',NEW.id::text); END LOOP; RETURN NEW; END $$;
CREATE TRIGGER evaluation_rank_changed AFTER UPDATE OF status ON public."Points_Transactions" FOR EACH ROW EXECUTE FUNCTION public.evaluation_notify_rank_change();
REVOKE ALL ON FUNCTION public.evaluation_notify_rank_change() FROM PUBLIC,anon,authenticated;